// Kept per module so two tiers loaded into one isolate never replace each other's providers.
const registry = new DatabaseRegistry([
  provideBucketClient,
  provideGA4AnalyticsClient,
  provideGEMINI_AGENT,
  provideGEMINI_BATCH_PROVIDER,
  provideKVClient,
  providePRISIMA_CLIENT,
  providePRISIMA_FULLTEXT_CLIENT,
  providePRISIMA_HYPERDRIVE_CLIENT,
  providePRISMA_LOGS_CLIENT,
  provideQueueClient,
  provideRedisClient,
  provideSlaxAlertBotClient,
  provideStripeClient,
  provideVECTORIZE_CLIENTS,
  provideVectorEmbeddingClient,
  provideVectorIndexClient,
  provideVectorPreferenceClient,
  provideVectorPreferenceStores,
  provideVectorSourceRepo
])

export function initializeInfrastructure(ctx: ContextManager, targetContainer: Container) {
  const selected = container.isRegistered(DatabaseRegistry) ? container.resolve(DatabaseRegistry) : registry
  selected.register(ctx, targetContainer)
}

export function initializeCore() {
  return {
    container
  }
}
